const dsl = `workspace "Parcel Tracker" "A parcel delivery tracking platform" {
    model {
        customer = person "Customer" "A customer who looks up the status of their parcels"

        parcelTracker = softwareSystem "Parcel Tracker" "The parcel delivery tracking platform, owned and operated by our company" {
            webPortal = container "Web Portal" "Where customers look up shipments" "Web application" {
                webPricingRules = component "Pricing Rules Library" "A shared library that computes delivery prices from weight and zone"
            }

            dispatchService = container "Dispatch Service" "Assigns parcels to couriers" "Service" {
                dispatchPricingRules = component "Pricing Rules Library" "A shared library that computes delivery prices from weight and zone"
            }

            database = container "Database" "Stores shipments and dispatch records" "Database"
        }

        emailProvider = softwareSystem "Email Delivery Provider" "An email delivery provider operated by a different organization"

        customer -> webPortal "looks up the status of their parcels" "HTTPS"
        dispatchService -> emailProvider "sends customer notification emails through" "SMTP"
        webPortal -> database "stores and retrieves shipments in" "SQL"
        dispatchService -> database "stores and retrieves dispatch records in" "SQL"
    }
    views {
        systemContext "SystemContext" "System Context" "The Parcel Tracker system and its external actors." {
            include *
            autoLayout
        }
        container "Containers" "Containers" "The containers within the Parcel Tracker system." {
            include *
            autoLayout
        }
        component "WebPortalComponents" "Web Portal Components" "The components within the Web Portal." {
            include *
            autoLayout
        }
        component "DispatchServiceComponents" "Dispatch Service Components" "The components within the Dispatch Service." {
            include *
            autoLayout
        }
    }
}`;
const [validate, parse, inspect] = await Promise.allSettled([
  tools.structurizr.validate({ dsl }),
  tools.structurizr.parse({ dsl }),
  tools.structurizr.inspect({ dsl }),
]);
return { validate, parse, inspect };

